/**
 * Dynamischer Netzanschluss: Konfiguration, Aktivierung und Vorschau nutzen die geschützte Runtime-API mit einem
 * gemeinsamen 5-s-Abbruchbudget. Mutationen werden nach Timeout nicht wiederholt:
 * Der Server könnte sie bereits gespeichert haben; zuerst erneut lesen.
 * Autorisierungs- und Versionsfehler werden niemals über einen anderen Port umgangen.
 */
export async function dynamicGridRequest(suffix = '', payload: unknown = null): Promise<unknown> {
  if (!['', '/status', '/config', '/preview'].includes(suffix)) throw new Error('Ungültiger Netzanschluss-Aufruf.');
  const deadline = Date.now() + 5000;
  const ports = await getRuntimePorts();
  let lastError: unknown = null;
  for (const port of ports) {
    const remaining = deadline - Date.now();
    if (remaining <= 0) break;
    try {
      const url = `${buildRuntimeBaseUrl(port)}/api/dynamic-grid${suffix}`;
      return payload === null
        ? await fetchJsonWithTimeout(url, remaining, { credentials: 'include' })
        : await postJsonWithTimeout(url, payload, remaining, { credentials: 'include' });
    } catch (error) {
      lastError = error;
      if (payload !== null || [400, 401, 403, 404, 409, 422].includes(getErrorStatus(error))) throw error;
    }
  }
  throw lastError || new Error('Dynamischer Netzanschluss nicht erreichbar.');
}
